const files = {
  "app/globals.css": "",
  "app/[locale]/page.tsx": "",
  "app/[locale]/layout.tsx": "",
  "app/[locale]/groupe/page.tsx": "",
  "app/[locale]/equipes/page.tsx": "",
  "app/[locale]/actualites/[slug]/page.tsx": "",
  "app/[locale]/datacenters/page.tsx": "",
  "app/[locale]/datacenters/[slug]/page.tsx": "",
  "app/[locale]/offres/page.tsx": "",
  "components/SiteHeader.tsx": "",
  "components/SiteFooter.tsx": "",
  "components/BrochureButton.tsx": "",
  "components/LangSwitcher.tsx": "",
  "components/ArticleSearch.tsx": "",
  "components/OffresPersonas.tsx": "",
  "components/OffreIcon.tsx": "",
  "components/Logo.tsx": "",
  "components/AltareaLogo.tsx": "",
  "lib/wordpress.ts": "",
  "lib/sample-data.ts": "",
  "lib/personas.ts": "",
  "components/MapClient.tsx": "",
  "components/Services.tsx": "",
  "messages/fr.json": "",
  "messages/en.json": "",
  "public/altarea-mark.svg": "",
  "public/altarea-lockup.svg": "",
  "public/favicon.svg": "",
};

for (const [path, b64] of Object.entries(files)) {
  const dir = path.substring(0, path.lastIndexOf("/"));
  if (dir) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path, Buffer.from(b64, "base64").toString("utf8"));
  console.log("ecrit :", path);
}

console.log("\nCorrectifs appliques. Pense a commit + push.");
